import { Context, Next } from "koa"

export function createMiddleware(
  handler: (ctx: Context, next: Next) => Promise<void>,
) {
  return async (ctx: Context, next: Next) => {
    await handler(ctx, next)
  }
}

import sql from "@/src/utils/db"
import { RESET_PASSWORD, sendVerifyEmail } from "@/src/utils/emails"
import Context from "@/src/utils/koa"
import { sendTelegramMessage } from "@/src/utils/notifications"
import { sendEmail } from "@/src/utils/sendEmail"
import Router from "koa-router"
import { z } from "zod"
import { hashPassword, signJwt, verifyJwt, verifyPassword } from "./utils"

const auth = new Router({
  prefix: "/auth",
})

auth.post("/signup", async (ctx: Context) => {
  const bodySchema = z.object({
    email: z.string().email(),
    password: z.string().min(6),
    name: z.string(),
    orgName: z.string().optional(),
    projectName: z.string().optional(),
    employeeCount: z.string().optional(),
    orgId: z.string().optional(),
    signupMethod: z.enum(["signup", "join"]),
  })

  const {
    email,
    password,
    name,
    orgName,
    projectName,
    employeeCount,
    orgId,
    signupMethod,
  } = bodySchema.parse(ctx.request.body)

  if (orgName?.includes("https://") || name.includes("http://")) {
    ctx.throw(403, "Bad request")
    return
  }

  const [existingUser] = await sql`
    select * from account where email = ${email}
  `
  if (existingUser) {
    ctx.throw(403, "User already exists")
  }

  if (signupMethod === "signup") {
    const { user, org } = await sql.begin(async (sql) => {
      const plan = process.env.DEFAULT_PLAN || "free"

      const [org] =
        await sql`insert into org ${sql({ name: orgName || `${name}'s Org`, plan })} returning *`

      const newUser = {
        name,
        passwordHash: await hashPassword(password),
        email,
        orgId: org.id,
        role: "admin",
        verified: process.env.SKIP_EMAIL_VERIFY ? true : false,
      }
      const [user] = await sql`
        insert into account ${sql(newUser)} 
        returning *
      `

      const newProject = {
        name: projectName,
        orgId: org.id,
      }
      const [project] = await sql`
        insert into project ${sql(newProject)} returning *
      `

      const publicKey = {
        type: "public",
        projectId: project.id,
        apiKey: project.id,
      }
      sql`
        insert into api_key ${sql(publicKey)}
      `
      const privateKey = [
        {
          type: "private",
          projectId: project.id,
        },
      ]
      await sql`
        insert into api_key ${sql(privateKey)}
      `

      return { user, org }
    })

    const token = await signJwt({
      userId: user.id,
      email: user.email,
      orgId: org.id,
    })

    await sendVerifyEmail(email, name)
    await sendTelegramMessage(
      `<b>🔔 New signup from ${email}</b>
      ${name} is ${
        signupMethod === "signup"
          ? `building ${projectName} @ ${orgName} (${employeeCount}).`
          : "joining an org."
      }`,
      "users",
    )

    ctx.body = { token }
    return
  } else if (signupMethod === "join") {
    const newUser = {
      name,
      passwordHash: await hashPassword(password),
      email,
      orgId,
      role: "member",
      verified: true,
    }
    const [user] = await sql`insert into account ${sql(newUser)} returning *`

    const token = await signJwt({
      userId: user.id,
      email: user.email,
      orgId,
    })

    ctx.body = { token }
    return
  }
})

auth.post("/login", async (ctx: Context) => {
  const bodySchema = z.object({
    email: z.string().email(),
    password: z.string(),
  })
  const { email, password } = bodySchema.parse(ctx.request.body)

  const [user] = await sql`
    select * from account where email = ${email}
  `
  if (!user) {
    ctx.status = 403
    ctx.body = { error: "Unauthorized", message: "Invalid email or password" }
    return
  }

  const passwordCorrect = await verifyPassword(password, user.passwordHash)

  if (!passwordCorrect) {
    ctx.status = 403
    ctx.body = { error: "Unauthorized", message: "Invalid email or password" }
    return
  }

  const token = await signJwt({
    userId: user.id,
    email: user.email,
    orgId: user.orgId,
  })

  ctx.body = { token }
})

auth.post("/request-password-reset", async (ctx: Context) => {
  try {
    const { email } = ctx.request.body as { email: string }
    const [user] = await sql`select id from account where email = ${email}`

    const ONE_HOUR = 60 * 60
    const token = await signJwt({ email }, ONE_HOUR)

    await sql`update account set recovery_token = ${token} where id = ${user.id}`

    const link = `${process.env.NEXT_PUBLIC_APP_URL}/reset-password?token=${token}`

    await sendEmail(RESET_PASSWORD(email, link))

    ctx.body = { ok: true }
  } catch (error) {
    console.error(error)
    // Do not send error message to client if email is not found
    ctx.body = {}
  }
})

auth.post("/reset-password", async (ctx: Context) => {
  const bodySchema = z.object({
    token: z.string(),
    password: z.string(),
  })
  const { token, password } = bodySchema.parse(ctx.request.body)

  const {
    payload: { email },
  } = await verifyJwt<{ email: string }>(token)

  const passwordHash = await hashPassword(password)

  const [user] = await sql`
    update account set password_hash = ${passwordHash} where email = ${email} returning *
  `

  const authToken = await signJwt({
    userId: user.id,
    email: user.email,
    orgId: user.orgId,
  })

  ctx.body = { token: authToken }
})

export default auth

import sql from "@/src/utils/db"
import Context from "@/src/utils/koa"
import * as jose from "jose"
import { SignJWT } from "jose"
import { Next } from "koa"
import * as argon2 from "argon2"

import bcrypt from "bcrypt"
import { validateUUID } from "@/src/utils/misc"

export async function verifyPassword(
  password: string,
  hash: string,
): Promise<boolean> {
  if (hash.startsWith("$argon2")) {
    return argon2.verify(hash, password)
  } else if (
    hash.startsWith("$2a") ||
    hash.startsWith("$2b") ||
    hash.startsWith("$2y")
  ) {
    return bcrypt.compare(password, hash)
  } else {
    throw new Error("Unknown hash type")
  }
}

export async function hashPassword(password: string): Promise<string> {
  return argon2.hash(password)
}

const ONE_MONTH = 60 * 60 * 24 * 30
export function signJwt(
  payload: any,
  expiresIn: number = ONE_MONTH,
): Promise<string> {
  const iat = Math.floor(Date.now() / 1000)
  const exp = iat + expiresIn

  return new SignJWT(payload)
    .setProtectedHeader({ alg: "HS256", typ: "JWT" })
    .setExpirationTime(exp)
    .setIssuedAt(iat)
    .setNotBefore(iat)
    .sign(new TextEncoder().encode(process.env.JWT_SECRET))
}

export function verifyJwt<Payload>(token: string) {
  return jose.jwtVerify<Payload>(
    token,
    new TextEncoder().encode(process.env.JWT_SECRET),
  )
}

// TODO: shared
interface SessionData {
  userId: string
  email: string
  orgId: string
}

const publicRoutes = [
  new RegExp(`/auth/.+`),
  "/api/report", // required legacy route
  "/api/v1/template", // legacy template route
  "/v1/health",
  "/v1/health-check",
  "/webhooks/stripe",
  "/auth/user/password/reset",
  `/v1/runs/ingest`,
  new RegExp(`/v1/runs/.+/public`), // public run data
  new RegExp(`/v1/runs/.+/feedback`), // getFeedback in SDKs
  `/v1/template_versions/latest`,
  "/v1/users/verify-email",
  "/v1/users/send-verification",
  new RegExp(`/v1/datasets/.+`), // getDataSets in SDKs
  `/v1/evaluations/run`,
]

// TODO: we need to refactor this / find a more elegant way to use this middleware because it doesn't make any sense what's hapenning here
export async function authMiddleware(ctx: Context, next: Next) {
  ctx.state.projectId = ctx.request?.query?.projectId as string

  const isPublicRoute = publicRoutes.some((route) =>
    typeof route === "string" ? route === ctx.path : route.test(ctx.path),
  )

  const bearerToken = ctx.request?.headers?.authorization?.split(" ")[1]

  if (isPublicRoute && (!bearerToken || validateUUID(bearerToken))) {
    if (validateUUID(bearerToken)) {
      ctx.state.projectId = bearerToken as string
    }
    await next()
    return
  }

  if (isPublicRoute) {
    const bearerToken = ctx.request?.headers?.authorization?.split(" ")[1]

    if (typeof bearerToken === "string") {
      ctx.state.projectId = bearerToken
    }
    await next()
    return
  }

  try {
    if (!bearerToken) {
      throw new Error("No bearer token provided.")
    }
    const { payload } = await verifyJwt<SessionData>(bearerToken)

    ctx.state.userId = payload.userId
    ctx.state.orgId = payload.orgId

    if (ctx.state.projectId) {
      // CHeck if user has access to project

      const [project] = await sql`
        select id from project where id = ${ctx.state.projectId} and org_id = ${ctx.state.orgId}
      `

      if (!project) {
        throw new Error("Project not found")
      }
    }
  } catch (error) {
    console.error(error)
    ctx.status = 401
    ctx.body = {
      error: "Unauthorized",
      message: "You must be logged in to access this page",
    }
    return
  }

  await next()
}

