})

users.get("/me/org", async (ctx: Context) => {
  const { userId } = ctx.state

  // TODO: (low priority) merge queries
  const [org] = await sql`
      select
        id,
        limited,
        name,
        plan,
        plan_period,
        canceled,
        play_allowance,
        stripe_customer
      from
        org
      where
        id = (select org_id from account where id = ${userId})
    `

  if (!org) {
    ctx.status = 401
    ctx.body = { message: "Unauthorized" }
    return
  }

  const users = await sql`
      select
        id,
        name,
        email,
        role
      from
        account
      where
        org_id = ${org.id}
      order by
        case role
          when 'admin' then 1
          when 'member' then 2
          else 3
        end,
        name
