import { useLocalStorage } from "@mantine/hooks"
import { decodeJwt } from "jose"
import { createContext, useContext, useEffect, useMemo } from "react"
import Router from "next/router"

const SIGN_OUT_EVENT = "sign-out"
export async function signOut() {
  window.localStorage.clear()
  window.dispatchEvent(new Event(SIGN_OUT_EVENT))
}

interface AuthContext {
  isSignedIn: boolean
  setJwt: (
    val: string | ((prevState: string | null) => string | null) | null,
  ) => void
  signOut: () => void
}

const AuthContext = createContext<AuthContext | null>(null)

function checkJwt(jwt) {
  try {
    const payload = decodeJwt(jwt)
    const exp = payload.exp

    if (!exp || exp < Date.now() / 1000) {
      throw new Error("Token expired")
    }
    return true
  } catch (error) {
    return false
  }
}

export function AuthProvider({ children }) {
  const [jwt, setJwt, removeJwt] = useLocalStorage<string | null>({
    key: "auth-token",
    getInitialValueInEffect: false,
    serialize: (value) => value || "",
    deserialize: (localStorageValue) => localStorageValue || null,
    defaultValue: null,
  })

  const isSignedIn = useMemo(() => checkJwt(jwt), [jwt])

  function doSignOut() {
    removeJwt()
    // Router.push("/login")
  }

  useEffect(() => {
    window.addEventListener(SIGN_OUT_EVENT, doSignOut)
    return () => {
      window.removeEventListener(SIGN_OUT_EVENT, doSignOut)
    }
  }, [])

  return (
    <AuthContext.Provider value={{ isSignedIn, setJwt, signOut }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === null) {
    throw new Error("useAuth must be used within a AuthProvider")
  }
  return context
}

import { clearUndefined } from "./ingest"
import OpenAI from "openai"
import { completion } from "litellm"
import { MODELS } from "shared"

function convertInputToOpenAIMessages(input: any[]) {
  return input.map(({ role, content, text, functionCall, toolCalls, name }) => {
    return clearUndefined({
      role: role.replace("ai", "assistant"),
      content: content || text,
      function_call: functionCall || undefined,
      tool_calls: toolCalls || undefined,
      name: name || undefined,
    })
  })
}

const OPENROUTE_HEADERS = {
  Authorization: `Bearer ${process.env.OPENROUTER_API_KEY}`,
  "HTTP-Referer": `https://lunary.ai`, // Optional, for including your app on openrouter.ai rankings.
  "X-Title": `Lunary.ai`,
  "Content-Type": "application/json",
}

// Replace {{variable}} with the value of the variable using regex
export function compileTemplate(
  content: string,
  variables: Record<string, string>,
) {
  const regex = /{{(.*?)}}/g
  return content.replace(regex, (_, g1) => variables[g1] || "")
}

export function compileChatMessages(content: any, variables: any) {
  // Create a deep copy of the content to prevent mutation of the original array
  let copy = JSON.parse(JSON.stringify(content))

  if (variables) {
    for (const item of copy) {
      item.content = compileTemplate(item.content, variables)
    }
  }

  return copy
}

export async function runAImodel(
  content: any,
  extra: any,
  variables: Record<string, string> | undefined = undefined,
  model: string,
  stream: boolean = false,
) {
  const copy = compileChatMessages(content, variables)

  const messages = convertInputToOpenAIMessages(copy)

  let method: any

  const modelObj = MODELS.find((m) => m.id === model)

  const useAnthropic = modelObj?.provider === "anthropic"
  const useOpenRouter = modelObj?.provider === "openrouter"

  if (useAnthropic) {
    method = completion
  } else {
    const openAIparams = useOpenRouter
      ? {
          apiKey: process.env.OPENROUTER_API_KEY,
          baseURL: "https://openrouter.ai/api/v1",
          defaultHeaders: OPENROUTE_HEADERS,
        }
      : {
          apiKey: process.env.OPENAI_API_KEY,
        }

    const openai = new OpenAI(openAIparams)

    method = openai.chat.completions.create.bind(openai.chat.completions)
  }

  const res = await method({
    model,
    messages,
    stream,
    temperature: extra?.temperature,
    max_tokens: extra?.max_tokens,
    top_p: extra?.top_p,
    top_k: extra?.top_k,
    presence_penalty: extra?.presence_penalty,
    frequency_penalty: extra?.frequency_penalty,
    stop: extra?.stop,
    functions: extra?.functions,
    tools: extra?.tools,
    seed: extra?.seed,
  })

  if (!stream && useOpenRouter && res.id) {
    // OpenRouter API to Querying Cost and Stats
    const generationData: any = await fetch(
      `https://openrouter.ai/api/v1/generation?id=${res.id}`,
      { headers: OPENROUTE_HEADERS },
    ).then((res) => res.json())

    res.usage = {
      prompt_tokens: generationData?.data?.tokens_prompt,
      completion_tokens: generationData?.data?.tokens_completion,
    }
  }

  return res
}

import openai from "@/src/utils/openai"
import lunary from "lunary"

export default async function aiAssert(sentence: string, assertion: string) {
  const template = await lunary.renderTemplate("assert", {
    response: sentence,
    assertion,
  })

  const res = await openai.chat.completions.create(template)

  const output = res.choices[0]?.message?.content

  if (!output) throw new Error("No output from AI")

  const result = output.split("\n")[0].toLowerCase().replace(".", "").trim()
  const reason = output.split("\n").slice(1).join("\n")

  return {
    passed: result === "yes",
    reason,
  }
}

import sql from "@/src/utils/db"
import { compileChatMessages } from "@/src/utils/playground"

export async function getDatasetById(datasetId: string, projectId: string) {
  const [dataset] =
    await sql`select * from dataset where  id = ${datasetId} and project_id = ${projectId}`

  if (!dataset) {
    throw new Error("Dataset not found")
  }

  dataset.prompts =
    await sql`select * from dataset_prompt where dataset_id = ${datasetId} order by created_at asc`

  for (const prompt of dataset.prompts) {
    prompt.variations =
      await sql`select * from dataset_prompt_variation where prompt_id = ${prompt.id} order by created_at asc`
  }

  return dataset
}

// TODO: refacto?
export async function getDatasetBySlug(slug: string, projectId: string) {
  const rows = await sql`
    select
      d.id as id,
      d.project_id as project_id,
      d.slug as slug,
      p.id as prompt_id,
      d.owner_id as owner_id,
      p.messages as prompt_messages,
      pv.id as variation_id,
      pv.variables,
      pv.context,
      pv.ideal_output,
      pv.context
    from
      dataset d 
      left join dataset_prompt p on d.id = p.dataset_id
      left join dataset_prompt_variation pv on pv.prompt_id = p.id
    where 
      d.slug = ${slug}
      and d.project_id = ${projectId}
    `

  const { id, ownerId } = rows[0]
  const dataset = {
    id,
    slug,
    ownerId,
    projectId,
    items: [],
  }

  for (const { promptMessages, variables, idealOutput, context } of rows) {
    const item = {
      input: compileChatMessages(promptMessages, variables),
      idealOutput,
      context,
    }
    dataset.items.push(item)
  }

  return dataset
}

